tool_input.command:
$h=@{'User-Agent'='dsh-agent'}
Write-Output '=== dsh-fish README (head) ==='
try { $t=(Invoke-WebRequest 'https://raw.githubusercontent.com/Fish-under-sea/dsh-fish/main/README.md' -Headers $h -TimeoutSec 25 -UseBasicParsing).Content; ($t -split "`n" | Select-Object -First 70) -join "`n" } catch { Write-Output "FAILED: $($_.Exception.Message)" }
Write-Output ''
Write-Output '=== dsh-fish packages/ ==='
try { (Invoke-RestMethod 'https://api.github.com/repos/Fish-under-sea/dsh-fish/contents/packages' -Headers $h -TimeoutSec 25) | Select-Object name,type | Format-Table -AutoSize | Out-String -Width 120 } catch { Write-Output "FAILED: $($_.Exception.Message)" }

$h=@{'User-Agent'='dsh-agent'}
try { $t=(Invoke-WebRequest 'https://raw.githubusercontent.com/Fish-under-sea/dsh-our-free-model-fish/main/README.md' -Headers $h -TimeoutSec 25 -UseBasicParsing).Content
  Write-Output "chars: $($t.Length)"
  $lines = $t -split "`n"
  Write-Output '--- head 40 ---'
  ($lines | Select-Object -First 40) -join "`n"
  Write-Output '--- lines mentioning 面积 / Fork / 差异 / 隐藏 ---'
  for ($i=0; $i -lt $lines.Count; $i++) { if ($lines[$i] -match '面积|本 Fork|与上游|差异|隐藏渠道|Fish') { Write-Output ("{0}: {1}" -f ($i+1), $lines[$i].Trim()) } }
} catch { Write-Output "FAILED: $($_.Exception.Message)" }
